      {modal === 'settings' && <div className=\"settings-content\"><label>Название дашборда<TextInput value={title} onUpdate={setTitle} size=\"l\" placeholder=\"Обзор бизнеса\"/></label><p className=\"muted\">Расположение виджетов и заметки сохраняются в этом браузере автоматически.</p><div className=\"setting-row\"><div><strong>Исходная раскладка</strong><p className=\"muted\">Вернуть восемь стандартных виджетов</p></div><Button view=\"outlined\" onClick={() => setModal('reset')}><Glyph data={ArrowRotateLeft} size={16}/>Восстановить</Button></div><Button view=\"action\" onClick={() => {if ("'!title.trim()) setTitle('"'Обзор бизнеса'); setModal(null); setToast('Настройки применены');}}>Готово</Button></div>}
      {modal === 'reset' && <><p className=\"modal-description\">Текущая раскладка, дополнительные виджеты и заметки будут заменены стандартным набором.</p><div className=\"modal-bottom\"><Button view=\"outlined\" onClick={() => setModal('settings')}>Отмена</Button><Button view=\"action\" onClick={resetLayout}>Восстановить</Button></div></>}
      {modal === 'help' && <div className=\"help-content\"><div><span>1</span><div><Text variant=\"subheader-2\">Выберите важное</Text><p>Откройте «Добавить виджет» и выберите показатели, графики или заметки.</p></div></div><div><span>2</span><div><Text variant=\"subheader-2\">Расположите по-своему</Text><p>Нажмите «Настроить». Перетаскивайте виджеты за заголовок, а за нижний правый угол — изменяйте размер. Через меню ⋯ можно перемещать виджеты с клавиатуры.</p></div></div><div><span>3</span><div><Text variant=\"subheader-2\">Возвращайтесь к своей картине</Text><p>Раскладка сохраняется в вашем браузере. Кнопка «Отмена» вернёт расположение до начала настройки.</p></div></div><Button view=\"action\" onClick={() => {setModal(null); startEdit();}}>Настроить мой дашборд</Button></div>}
      {modal === 'team' && <div className=\"settings-content\"><label>Рабочее пространство<TextInput size=\"l\" value={teamName} onUpdate={setTeamName}/></label><div className=\"team-member\"><span className=\"user-avatar\">АК</span><div><strong>Александр Ким</strong><p className=\"muted\">Владелец рабочего пространства</p></div><span className=\"personal-badge\">Вы</span></div><p className=\"muted\">Локальное рабочее пространство. Ваши настройки доступны в этом браузере.</p><Button view=\"action\" onClick={() => {if ("'!teamName.trim()) setTeamName('"'Команда Пульс'); setModal(null);}}>Сохранить</Button></div>}
      {modal === 'reports' && <div className=\"settings-content\"><p className=\"muted\">Сводка ключевых показателей за выбранный период.</p><Select options={PERIODS} value={[period]} onUpdate={([v]) => setPeriod(v)} size=\"l\" width=\"max\"/><div className=\"report-preview\"><Glyph data={FileText} size={30}/><div><strong>Обзор бизнеса</strong><p className=\"muted\">Выручка, заказы, клиенты и конверсия · CSV</p></div></div><Button view=\"action\" onClick={exportData}><Glyph data={ArrowDownToLine} size={16}/>Скачать отчёт</Button></div>}
      {modal === 'sources' && <div className=\"settings-content\"><div className=\"source-card\"><span className=\"catalog-icon\"><Glyph data={Database} size={24}/></span><div><Text variant=\"subheader-2\">Демонстрационный магазин</Text><p className=\"muted\">Заказы, клиенты и веб-аналитика</p></div><span className=\"status-pill paid\"><i/>Подключён</span></div><p className=\"muted\">Дашборд использует встроенный набор демонстрационных данных. Внешние сервисы не подключены.</p><Button view=\"outlined\" onClick={() => {setSavedAt('Демо-данные актуальны'); setToast('Демонстрационный набор обновлён'); setModal(null);}}>Обновить данные</Button></div>}
      {modal === 'notifications' && <div className=\"notifications\"><div className=\"notification-item\"><span className=\"catalog-icon\"><Glyph data={Target} size={22}/></span><div><Text variant=\"subheader-1\">Вы близки к цели"'!</Text><p>План по выручке за октябрь выполнен на 86%.</p><small className="muted">Сегодня, 14:35</small></div></div><div className="notification-item"><span className="catalog-icon"><Glyph data={Check} size={22}/></span><div><Text variant="subheader-1">Данные обновлены</Text><p>Сводка по заказам и клиентам готова к просмотру.</p><small className="muted">Сегодня, 14:35</small></div></div></div>}
    </Modal>
    {toast && <div className="app-toast" role="status"><span className="toast-icon"><Glyph data={Check} size={17}/></span>{toast}<IconButton icon={Xmark} label="Закрыть уведомление" onClick={() => setToast('"'')}/></div>}
  </DashboardContext.Provider>;
}
EOF"

args.command:
/bin/bash -lc "cat > src/styles.css <<'EOF'
.g-root {
  --g-font-family-sans: 'Inter', 'Helvetica Neue', Arial, sans-serif;
  --g-text-body-font-family: var(--g-font-family-sans);
  --g-text-header-font-family: var(--g-font-family-sans);
  --g-text-display-font-family: var(--g-font-family-sans);
  --g-border-radius-xs: 4px;
  --g-border-radius-s: 6px;
  --g-border-radius-m: 8px;
  --g-border-radius-l: 12px;
  --g-border-radius-xl: 16px;
  --g-button-border-radius: var(--g-border-radius-m);
  --g-text-display-1-font-size: 28px;
  --g-text-display-1-line-height: 36px;
  --g-text-display-1-font-weight: 600;
  --g-text-header-1-font-size: 24px;
  --g-text-header-2-font-size: 22px;
  --g-text-subheader-2-font-size: 15px;
  --g-text-body-2-font-size: 13px;
}
.g-root_theme_light {
  --g-color-base-brand: #7950dc;
  --g-color-base-brand-hover: #6840c7;
  --g-color-base-selection: #f1ebfc;
  --g-color-base-selection-hover: #e9defa;
  --g-color-line-brand: #7950dc;
  --g-color-line-focus: #7950dc;
  --g-color-text-brand: #7950dc;
  --g-color-text-brand-heavy: #6840c7;
  --g-color-text-brand-contrast: #ffffff;
  --g-color-text-link: #7950dc;
  --g-color-text-link-hover: #6840c7;
  --g-color-text-primary: #282733;
  --g-color-text-secondary: #92909e;
  --g-color-text-hint: #aca9b5;
  --g-color-line-generic: #eae9ef;
  --g-color-base-background: #ffffff;
  --g-color-base-float: #ffffff;
  --g-color-base-generic: #f7f7fa;
  --g-color-base-simple-hover: #f7f5fb;
  --g-color-text-positive: #28a582;
  --g-color-base-positive-light: #eaf8f2;
  --g-color-text-warning: #ce914d;
  --g-color-base-warning-light: #fff4e7;
  --g-color-infographics-lavender: #baa0ef;
  --g-color-infographics-blue: #a9c9f1;
  --g-color-infographics-soft: #e7e8f1;
  --g-color-base-canvas: #f8f9fc;
}
.g-root_theme_dark {
  --g-color-base-brand: #aa84f4;
  --g-color-base-brand-hover: #ba99fa;
  --g-color-base-selection: #352b48;
  --g-color-base-selection-hover: #433456;
  --g-color-line-brand: #aa84f4;
  --g-color-line-focus: #aa84f4;
  --g-color-text-brand: #ba99fa;
  --g-color-text-brand-heavy: #cbb0ff;
  --g-color-text-brand-contrast: #21182f;
  --g-color-text-link: #ba99fa;
  --g-color-text-link-hover: #cbb0ff;
  --g-color-infographics-lavender: #7b64ad;
  --g-color-infographics-blue: #6a8ab5;
  --g-color-infographics-soft: #474458;
  --g-color-base-canvas: #18171e;
}
* { box-sizing: border-box; }
body { margin: 0; -webkit-font-smoothing: antialiased; }
button, input { font-family: inherit; }
.app-shell {
  --gn-aside-header-expanded-width: 224px;
  --gn-aside-header-background-color: var(--g-color-base-background);
  --gn-aside-header-expanded-background-color: var(--g-color-base-background);
  --gn-aside-header-collapsed-background-color: var(--g-color-base-background);
  --gn-aside-header-divider-vertical-color: var(--g-color-line-generic);
  --gn-aside-header-item-expanded-radius: var(--g-border-radius-m);
  --gn-aside-header-padding-top: 12px;
  --gn-aside-header-item-current-background-color: var(--g-color-base-selection);
  --gn-aside-header-item-current-color: var(--g-color-text-brand);
  --gn-aside-header-item-height: 44px;
}
.brand-name { font-size: 29px; font-weight: 750; letter-spacing: -1.2px; color: var(--g-color-text-primary); }
.brand-dot { color: var(--g-color-text-brand); }
.brand-icon { color: var(--g-color-text-brand); }
.sidebar-workspace { padding: var(--g-spacing-4) var(--g-spacing-3) 0; }
.workspace-button { height: 57px; --g-button-border-color: var(--g-color-line-generic); }
.workspace-letter { display: inline-flex; align-items: center; justify-content: center; width: 29px; height: 30px; flex-shrink: 0; border-radius: var(--g-border-radius-s); background: var(--g-color-base-selection); color: var(--g-color-text-brand); font-weight: 600; font-size: 15px; }
.workspace-text { text-align: left; display: inline-flex; flex-direction: column; line-height: 19px; font-size: 12px; font-weight: 550; margin: 0 var(--g-spacing-2); max-width: 126px; overflow: hidden; }
.workspace-text > span { color: var(--g-color-text-secondary); font-size: 10px; font-weight: 400; }
.sidebar-label { font-size: 9px; font-weight: 600; letter-spacing: 1.05px; color: var(--g-color-text-secondary); padding: var(--g-spacing-7) var(--g-spacing-2) var(--g-spacing-2); }
.sidebar-footer { padding: var(--g-spacing-3); }
.sidebar-tip { padding: var(--g-spacing-4); background: var(--g-color-base-generic); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); margin-bottom: var(--g-spacing-5); }
.tip-icon { color: var(--g-color-text-brand); display: block; margin-bottom: var(--g-spacing-3); }
.sidebar-tip .g-text { display: block; font-size: 12px; }
.sidebar-tip p { font-size: 11px; color: var(--g-color-text-secondary); line-height: 1.7; margin: var(--g-spacing-2) 0 var(--g-spacing-4); }
.sidebar-tip .g-button { font-size: 10px; --g-button-background-color: var(--g-color-base-background); }
.footer-nav { --g-button-text-align: left; --g-button-text-color: var(--g-color-text-secondary); margin-bottom: var(--g-spacing-1); font-size: 12px; }
.footer-nav svg { margin-right: var(--g-spacing-2); }
.sidebar-profile { display: flex; align-items: center; gap: var(--g-spacing-2); border-top: 1px solid var(--g-color-line-generic); margin-top: var(--g-spacing-4); padding-top: var(--g-spacing-5); padding-bottom: var(--g-spacing-2); }
.user-avatar { width: 33px; height: 33px; display: inline-flex; align-items: center; justify-content: center; flex-shrink: 0; font-size: 11px; font-weight: 600; border-radius: 50%; color: var(--g-color-text-brand-heavy); background: var(--g-color-base-selection); }
.profile-text { min-width: 0; flex: 1; display: flex; flex-direction: column; gap: var(--g-spacing-1); font-size: 11px; }
.profile-text strong { font-weight: 550; white-space: nowrap; }
.profile-text > span { font-size: 10px; color: var(--g-color-text-secondary); }
.main-shell { min-height: 100vh; background: var(--g-color-base-canvas); min-width: 0; }
.topbar { height: 73px; background: var(--g-color-base-background); border-bottom: 1px solid var(--g-color-line-generic); display: flex; align-items: center; justify-content: space-between; padding: 0 var(--g-spacing-8); gap: var(--g-spacing-4); }
.breadcrumb { display: flex; align-items: center; gap: var(--g-spacing-3); font-size: 12px; color: var(--g-color-text-secondary); min-width: 0; }
.breadcrumb strong { color: var(--g-color-text-primary); font-weight: 500; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.breadcrumb svg { flex-shrink: 0; }
.topbar-actions { display: flex; align-items: center; gap: var(--g-spacing-4); flex-shrink: 0; }
.search-button { color: var(--g-color-text-secondary); font-size: 12px; }
.search-button svg { margin-right: var(--g-spacing-2); }
kbd { font-family: inherit; font-size: 10px; margin-left: var(--g-spacing-6); padding: var(--g-spacing-1); border-radius: var(--g-border-radius-xs); background: var(--g-color-base-generic); }
.topbar-divider { height: 22px; width: 1px; background: var(--g-color-line-generic); }
.notification-button { position: relative; color: var(--g-color-text-secondary); }
.notification-button > i { position: absolute; right: 9px; top: 5px; width: 5px; height: 5px; border: 1px solid var(--g-color-base-background); border-radius: 50%; background: var(--g-color-base-brand); pointer-events: none; }
.dashboard-main { padding: var(--g-spacing-8); max-width: 1680px; margin: 0 auto; }
.page-heading { display: flex; justify-content: space-between; gap: var(--g-spacing-5); align-items: center; margin-bottom: var(--g-spacing-6); }
.title-line { display: flex; align-items: center; gap: var(--g-spacing-3); }
.title-line h1 { margin: 0; letter-spacing: -.8px; }
.personal-badge { display: inline-block; font-size: 10px; border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-s); color: var(--g-color-text-secondary); padding: var(--g-spacing-1) var(--g-spacing-2); white-space: nowrap; font-weight: 400; background: var(--g-color-base-background); }
.page-description { font-size: 12px; color: var(--g-color-text-secondary); margin: var(--g-spacing-2) 0 0; }
.heading-actions { display: flex; gap: var(--g-spacing-2); flex-shrink: 0; }
.heading-actions .g-button { font-size: 12px; }
.heading-actions svg { margin-right: var(--g-spacing-1); }
.dashboard-toolbar { display: flex; align-items: center; justify-content: space-between; gap: var(--g-spacing-4); min-height: 53px; border-bottom: 1px solid var(--g-color-line-generic); }
.dashboard-tabs { display: flex; align-self: stretch; gap: var(--g-spacing-6); }
.dashboard-tab { height: 100%; min-height: 53px; font-size: 12px; position: relative; --g-button-text-color: var(--g-color-text-secondary); --g-button-padding: 0; }
.dashboard-tab.active { --g-button-text-color: var(--g-color-text-brand); font-weight: 600; }
.dashboard-tab.active::after { position: absolute; content: ''; bottom: -1px; left: 0; right: 0; height: 2px; border-radius: var(--g-border-radius-xs); background: var(--g-color-base-brand); }
.filter-actions { display: flex; align-items: center; gap: var(--g-spacing-3); padding-bottom: var(--g-spacing-2); }
.period-select { display: flex; gap: var(--g-spacing-1); align-items: center; padding-left: var(--g-spacing-3); background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-m); color: var(--g-color-text-primary); }
.period-select .g-select { font-size: 11px; }
.filter-actions .g-button { font-size: 11px; background: var(--g-color-base-background); }
.filter-actions .g-button svg { margin-right: var(--g-spacing-1); }
.dashboard-status { display: flex; align-items: center; justify-content: space-between; min-height: 52px; gap: var(--g-spacing-3); color: var(--g-color-text-secondary); font-size: 10px; }
.dashboard-status > div { display: flex; align-items: center; gap: var(--g-spacing-2); }
.live-dot { width: 6px; height: 6px; display: inline-block; background: var(--g-color-text-positive); border-radius: 50%; }
.demo-label { border-left: 1px solid var(--g-color-line-generic); padding-left: var(--g-spacing-2); font-size: 9px; }
.save-status { display: flex; align-items: center; gap: var(--g-spacing-1); white-space: nowrap; }
.is-editing { color: var(--g-color-text-brand); }
.dashboard-grid { --dashkit-grid-item-border-radius: var(--g-border-radius-l); --dashkit-grid-item-edit-opacity: 1; --dashkit-placeholder-color: var(--g-color-base-brand); --dashkit-placeholder-opacity: .08; }
.editing-grid { background-image: radial-gradient(var(--g-color-line-generic) 1px, transparent 1px); background-size: 16px 16px; }
.widget { height: 100%; width: 100%; display: flex; flex-direction: column; overflow: hidden; background: var(--g-color-base-background); border: 1px solid var(--g-color-line-generic); border-radius: var(--g-border-radius-l); box-shadow: 0 2px 3px color-mix(in srgb, var(--g-color-sfx-shadow) 3%, transparent); }
.widget-editable { border-color: color-mix(in srgb, var(--g-color-line-brand) 40%, var(--g-color-line-generic)); }
.widget-header { display: flex; align-items: center; justify-content: space-between; padding: var(--g-spacing-4) var(--g-spacing-5) 0; min-height: 46px; gap: var(--g-spacing-2); flex-shrink: 0; }
.widget-drag-handle { display: flex; align-items: center; gap: var(--g-spacing-2); min-width: 0; }
.widget-drag-handle .g-text { overflow: hidden; text-overflow: ellipsis; white-space: nowrap; font-weight: 550; }
.widget-editable .widget-drag-handle { cursor: grab; touch-action: none; }
.widget-editable .widget-drag-handle:active { cursor: grabbing; }
.widget-header-actions { display: flex; flex-shrink: 0; align-items: center; color: var(--g-color-text-hint); }
.widget-header-actions .g-button { --g-button-text-color: var(--g-color-text-hint); }
.metric-icon { color: var(--g-color-text-secondary); display: flex; }
.metric-body { position: relative; padding: var(--g-spacing-1) var(--g-spacing-5) var(--g-spacing-4); flex: 1; }
.metric-value { position: relative; z-index: 1; font-variant-numeric: tabular-nums; letter-spacing: -.7px; white-space: nowrap; }
.metric-bottom { display: flex; align-items: center; gap: var(--g-spacing-1); margin-top: var(--g-spacing-2); position: relative; z-index: 1; }
.change { display: inline-flex; align-items: center; gap: 2px; color: var(--g-color-text-positive); font-size: 10px; font-weight: 550; }
.change.negative { color: var(--g-color-text-warning); }
.comparison { font-size: 9px; color: var(--g-color-text-secondary); }
.sparkline { position: absolute; bottom: 32px; right: 16px; width: 74px; height: 34px; opacity: .9; }
.widget-revenue .sparkline { width: 62px; }
.widget-revenue .metric-value { font-size: 26px; }
.muted { color: var(--g-color-text-secondary); }
.small { font-size: 11px; }
.trend-summary { display: flex; align-items: flex-start; justify-content: space-between; padding: var(--g-spacing-3) var(--g-spacing-5) 0; gap: var(--g-spacing-3); }
.trend-summary .g-text { font-size: 23px; font-weight: 550; letter-spacing: -.5px; }
.trend-summary .muted { margin-top: var(--g-spacing-1); font-size: 10px; }
.trend-growth { display: inline-flex; align-items: center; gap: 2px; margin-left: var(--g-spacing-3); color: var(--g-color-text-positive); padding: 3px var(--g-spacing-1); border-radius: var(--g-border-radius-xs); background: var(--g-color-base-positive-light); font-size: 10px; }
.chart-unit { font-size: 9px; color: var(--g-color-text-secondary); margin: var(--g-spacing-3) 0 0 var(--g-spacing-5); }
.revenue-chart { height: 160px; min-height: 80px; flex: 1; margin: 0 var(--g-spacing-5) 0 var(--g-spacing-3); --gcharts-axis-tick-color: var(--g-color-line-generic); }
.chart-legend { display: flex; justify-content: center; gap: var(--g-spacing-5); padding: var(--g-spacing-3) var(--g-spacing-2) var(--g-spacing-4); font-size: 10px; color: var(--g-color-text-secondary); }
.chart-legend > span { display: inline-flex; align-items: center; gap: var(--g-spacing-2); }
.legend-line { display: inline-block; width: 17px; height: 2px; background: var(--g-color-base-brand); }
.legend-line.previous { background: repeating-linear-gradient(to right, var(--g-color-infographics-lavender) 0 4px, transparent 4px 7px); }
.donut-container { height: 150px; min-height: 100px; flex: 1; max-height: 210px; position: relative; margin: var(--g-spacing-1) var(--g-spacing-6) 0; }
.donut-center { pointer-events: none; position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); display: flex; flex-direction: column; text-align: center; gap: var(--g-spacing-1); white-space: nowrap; }
.donut-center .g-text { font-weight: 550; letter-spacing: -.5px; }
.donut-center .small { font-size: 10px; }
.traffic-legend { padding: var(--g-spacing-2) var(--g-spacing-5) var(--g-spacing-4); display: flex; flex-direction: column; gap: var(--g-spacing-2); flex-shrink: 0; }
.traffic-legend > div { display: flex; justify-content: space-between; gap: var(--g-spacing-3); font-size: 11px; }
.traffic-legend > div > span { display: flex; align-items: center; gap: var(--g-spacing-2); color: var(--g-color-text-secondary); }
.traffic-legend i { width: 7px; height: 7px; display: inline-block; border-radius: 50%; }
.traffic-legend strong { font-weight: 500; }
.traffic-legend strong > span { padding-left: 2px; }
.table-description { padding: var(--g-spacing-1) var(--g-spacing-5) var(--g-spacing-3); font-size: 10px; }
.orders-table-wrap { overflow: auto; flex: 1; min-height: 0; }
.orders-table { --g-table-cell-padding: 10px 16px; --g-table-header-background-color: var(--g-color-base-generic); --g-table-header-color: var(--g-color-text-secondary); --g-table-border-color: var(--g-color-line-generic); font-size: 11px; }
.orders-table th { font-weight: 400; font-size: 10px; color: var(--g-color-text-secondary); background: var(--g-color-base-generic); }
.orders-table td { height: 43px; }
.customer-cell { display: flex; gap: var(--g-spacing-2); align-items: center; white-space: nowrap; }
.customer-avatar { width: 25px; height: 25px; border-radius: 50%; display: flex; align-items: center; justify-content: center; font-size: 8px; flex-shrink: 0; }
.purple { background: var(--g-color-base-selection); color: var(--g-color-text-brand); }
.blue { background: var(--g-color-base-info-light); color: var(--g-color-text-info); }
