    for (const a of next.layout) {
      expect(a.x + a.w).toBeLessThanOrEqual(12);
      for (const b of next.layout) {
        if (a.i "'!== b.i) expect(a.x < b.x + b.w && a.x + a.w > b.x && a.y < b.y + b.h && a.y + a.h > b.y).toBe(false);
      }
    }
  });
